//! The types shared by the bidirectional JSON-RPC server and client: the WebSocket message format,
//! connection identity, and the connection manager trait.
//!
//! Services generated by `ras-jsonrpc-bidirectional-macro` receive a [`ConnectionId`] and a
//! `&dyn` [`ConnectionManager`] in every handler, and send through it. Otherwise this crate is
//! mostly used through `ras-jsonrpc-bidirectional-server` and `ras-jsonrpc-bidirectional-client`.
//!
//! The main items:
//!
//! - [`BidirectionalMessage`], every message on the socket, serialized as a JSON object with a
//!   snake-case `type` field; [`ServerNotification`] and [`BroadcastMessage`] are its payloads
//!   for notifications to one connection and to a topic;
//! - [`ConnectionId`] and [`ConnectionInfo`], a connection's identity and what the server knows
//!   about it;
//! - [`ConnectionManager`], for tracking connections and sending or broadcasting to them, with
//!   helpers in [`manager::ConnectionManagerExt`];
//! - [`MessageSender`] and [`MessageSenderExt`], for sending on one connection;
//! - [`BidirectionalError`] and the [`Result`] alias.
//!
//! The crate has no Cargo features and builds for `wasm32`; `WebSocketMessageSender` is only
//! available on native targets. See the [README].
//!
//! [README]: https://github.com/JedimEmO/rust-api-stack/blob/master/crates/rpc/bidirectional/ras-jsonrpc-bidirectional-types/README.md

pub mod error;
pub mod manager;
pub mod sender;

pub use error::BidirectionalError;
pub use manager::ConnectionManager;
#[cfg(not(target_arch = "wasm32"))]
pub use sender::WebSocketMessageSender;
pub use sender::{MessageSender, MessageSenderExt, NoOpMessageSender};

mod connection;
mod wire;
pub use connection::{ConnectionId, ConnectionInfo};
pub use wire::{BidirectionalMessage, BroadcastMessage, ServerMessage, ServerNotification};

/// Result type for bidirectional operations
pub type Result<T> = std::result::Result<T, BidirectionalError>;

#[cfg(test)]
mod tests;
